input.command:
cd /tmp/probe/work-checks-core-error && mkdir -p np && cd np
cat > n1.c <<'EOF'
void f() {
    int *p = 0;
    *p = 1;
}
EOF
cat > n2.c <<'EOF'
void f(int *p) {
    *p = 1;
    if (p) {}
}
EOF
cat > n3.c <<'EOF'
void f(int *p) {
    if (!p) {}
    *p = 1;
}
EOF
cat > n4.c <<'EOF'
void f() {
    int *p = 0;
    int *q = p + 1;
}
EOF
cat > n5.c <<'EOF'
struct S { int x; };
void f(struct S *s) {
    if (s == 0) {
        s->x = 1;
    }
}
EOF
cat > n6.cpp <<'EOF'
struct S { int x; };
void f() {
    S *s = nullptr;
    s->x = 1;
}
EOF
cat > n7.c <<'EOF'
void f() {
    int *p = NULL;
    *p = 1;
}
EOF
cat > n8.cpp <<'EOF'
void f(int *p) {
    int x = *p;
    if (p != nullptr) x++;
}
EOF
cat > n9.c <<'EOF'
void g(int *p);
void f() {
    int *p = 0;
    p[0] = 1;
}
EOF
for f in n1.c n2.c n3.c n4.c n5.c n6.cpp n7.c n8.cpp n9.c; do ../cmp.sh $f; done

